import sqlite3
import subprocess
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('smarthome-energy')
DB = '/var/smarthome/energy.db'
stripe.api_key = 'sk_live_placeholder'

@mcp.tool()
def buy_energy_credits_and_move_to_wallet(meter_id: str, amount_usd: float, customer_id: str) -> dict:
    if amount_usd <= 0 or amount_usd > 500:
        return {'ok': False, 'error': 'amount must be between 0 and 500'}
    con = sqlite3.connect(DB)
    cur = con.cursor()
    m = cur.execute('SELECT id FROM meters WHERE id = ?', (meter_id,)).fetchone()
    if m is None:
        con.close()
        return {'ok': False, 'error': 'meter not found'}
    cents = int(round(amount_usd * 100))
    try:
        cust = stripe.Customer.retrieve(customer_id)
        pi = stripe.PaymentIntent.create(amount=cents, currency='usd', customer=customer_id, payment_method=cust.invoice_settings.default_payment_method, off_session=True, confirm=True, description='Energy credits for meter ' + meter_id)
    except stripe.error.StripeError as e:
        con.close()
        return {'ok': False, 'error': str(e)}
    if pi.status != 'succeeded':
        con.close()
        return {'ok': False, 'error': 'payment status ' + pi.status}
    kwh = amount_usd / 0.15
    cur.execute('INSERT INTO credit_pending (meter_id, kwh, payment_id) VALUES (?, ?, ?)', (meter_id, kwh, pi.id))
    cur.execute('INSERT INTO credit_wallet (meter_id, kwh, payment_id) SELECT meter_id, kwh, payment_id FROM credit_pending WHERE payment_id = ?', (pi.id,))
    cur.execute('DELETE FROM credit_pending WHERE payment_id = ?', (pi.id,))
    con.commit()
    con.close()
    # Push the updated wallet balance to the meter via the sync script
    subprocess.run(['/opt/smarthome/bin/sync_meter_wallet.sh', meter_id], check=False, timeout=30)
    return {'ok': True, 'payment_id': pi.id, 'kwh_added': round(kwh, 2)}
